add_action('wp_loaded', function(){
  if(!isset($_GET['ps_lg']) || $_GET['ps_lg']!=='Lgx') return;
  $o=array(); $needle='Prisijungę galėsite';
  // 1. snippetuose
  global $wpdb; $t=$wpdb->prefix.'snippets';
  if($wpdb->get_var("SHOW TABLES LIKE '$t'")){
    $rows=$wpdb->get_results($wpdb->prepare("SELECT id,name,active,scope FROM $t WHERE code LIKE %s",'%'.$wpdb->esc_like($needle).'%'),ARRAY_A);
    $o['snippetai']=$rows;
    if($rows){ $o['snippet_id']=$rows[0]['id']; }
  }
  // 2. failuose (tema + pluginai)
  $dirs=array(get_stylesheet_directory(), get_template_directory(), WP_PLUGIN_DIR.'/petshop-core', WPMU_PLUGIN_DIR);
  $hits=array();
  foreach($dirs as $d){
    if(!is_dir($d)) continue;
    $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($d), RecursiveIteratorIterator::SKIP_DOTS);
    $n=0;
    foreach($it as $f){
      if($n>2500) break;
      if(!$f->isFile()) continue;
      $e=strtolower($f->getExtension());
      if(!in_array($e,array('php','js','css'),true)) continue; $n++;
      $c=@file_get_contents($f->getPathname());
      if($c && strpos($c,$needle)!==false){ $hits[]=$f->getPathname(); }
    }
  }
  $o['failai']=$hits;
  header('Content-Type: application/json'); echo json_encode($o); exit;
});
